	//   - into_blocks_dynamic<'j','J','j','r'>(tile_j) splits 'j' into
	//     a block index 'J' and an intra-block index 'j'. The auxiliary
	//     dimension 'r' is a presence flag (length 0 or 1) that guards
	//     incomplete tiles in the last block.
	//   - hoist<'J'> makes 'J' the outermost loop dimension in the j-space.
	auto trav = traverser(A, B, tmp, x, y)
		.order(into_blocks_dynamic<'j', 'J', 'j', 'r'>(lit<tile_j>) ^ hoist<'J'>());

	#pragma scop
