		// changes the logical traversal to:
		//   for J (tiles) in 0..ceil(N/tile_j)-1
		//     for j (within-tile) and presence r
		// which is equivalent to a single for j in [0, N) with the same order
		// of global j-indices. The extra 'J' and 'r' coordinates are handled
		// by the structure and traverser.
		row_trav.for_each([&](auto s) {
			// s has indices ('i', 'J', 'j', 'r'); all three matrices/vectors
			// A, B, and x are viewed through the same blocked ('J','j','r')
			// coordinates, so we can reuse s for all of them. The extra 'i'
			// coordinate is simply ignored by x (which has no 'i' dimension).
			num_t xj = x[s];

			tmp_acc += A[s] * xj;
			y_acc   += B[s] * xj;
		});

		// Write back once per row; this preserves the original semantics:
		//   tmp[i] == Σ_j A[i,j]*x[j]
		//   y[i]   == alpha * tmp[i] + beta * Σ_j B[i,j]*x[j]
		tmp[si] = tmp_acc;
		y[si]   = alpha * tmp_acc + beta * y_acc;
	});
	#pragma endscop
}

