// computation kernel
//
// Optimized version of the original GESUMMV kernel:
//
//   tmp[i] = Σ_j A[i,j] * x[j]
//   y[i]   = alpha * tmp[i] + beta * Σ_j B[i,j] * x[j]
//
// Main optimizations:
//  - Use scalar accumulators per row (kept in registers) instead of repeatedly
//    loading/storing tmp[i] and y[i] inside the inner j-loop.
//  - Tile both i and j using into_blocks_dynamic to improve cache locality
//    while correctly handling non-multiple sizes.
//  - Hoist tile indices so that the traversal order is:
//        I (row tiles) → i (rows in tile) → J (column tiles) → j (cols in tile)
//    which preserves the original reduction order over j.
//
[[gnu::flatten, gnu::noinline]]
void kernel_gesummv(num_t alpha, num_t beta, auto A, auto B, auto tmp, auto x, auto y) {
	using namespace noarr;

	// Tuned tile sizes for a modern x64 CPU. They do not need to divide N;
	// into_blocks_dynamic handles edge tiles safely via guard dimensions.
	constexpr std::size_t tile_i = 64;   // rows per tile
	constexpr std::size_t tile_j = 256;  // columns per tile

	#pragma scop
	traverser(A, B, tmp, x, y)
		// 1) Block rows: i -> (I, i, r)
		//    - 'I'  : row-tile index
		//    - 'i'  : row inside the tile
		//    - 'r'  : presence guard (length 0/1 for incomplete last tile)
		.order(
			into_blocks_dynamic<'i', 'I', 'i', 'r'>(noarr::lit<tile_i>)
			^
			// 2) Block columns: j -> (J, j, s)
			//    - 'J'  : column-tile index
			//    - 'j'  : column inside the tile
			//    - 's'  : presence guard (length 0/1 for incomplete last tile)
			into_blocks_dynamic<'j', 'J', 'j', 's'>(noarr::lit<tile_j>)
			^
			// 3) Hoist tile indices: make I outermost, then J.
			hoist<'J'>() ^ hoist<'I'>()
		)
		// Outer loop over row tiles I
		.template for_dims<'I'>([=](auto trav_I) {
			// Loop over actual rows i in tile I; 'r' skips padded rows in
			// the final partial tile when N is not a multiple of tile_i.
			trav_I.template for_dims<'i', 'r'>([=](auto trav_row) {
				// State identifying this row (contains 'i', plus tile info);
				// can be used directly to index tmp and y (extra dims ignored).
				auto row_state = trav_row.state();

				// Per-row accumulators kept in registers
				num_t sumA = (num_t)0.0; // Σ_j A[i,j] * x[j]
				num_t sumB = (num_t)0.0; // Σ_j B[i,j] * x[j]

				// Loop over column tiles J for this row
				trav_row.template for_dims<'J'>([&](auto trav_J) {
					// Loop over actual columns j in tile J; 's' skips padded
					// columns in the final partial tile.
					trav_J.template for_dims<'j', 's'>([&](auto trav_js) {
						auto s = trav_js.state(); // has i and j (and tile/guard dims)

						// Access x[j], A[i,j], B[i,j] using the same state 's'.
						// Structures without a given dimension simply ignore it.
						num_t xj = x[s];
						sumA += A[s] * xj;
						sumB += B[s] * xj;
					});
				});

				// Write final results for this row.
				// This preserves the original semantics:
				//   tmp[i] = Σ_j A[i,j]*x[j]
				//   y[i]   = alpha * tmp[i] + beta * Σ_j B[i,j]*x[j]
				tmp[row_state] = sumA;
				y[row_state]   = alpha * sumA + beta * sumB;
			});
		});
	#pragma endscop
}

} // namespace

