		x[idx<'j'>(i)] = (num_t)(i % n) / n;

		// A[i][j], B[i][j]
		inner.for_each([=](auto s) {
			auto j = get_index<'j'>(s);

			A[s] = (num_t)((i * j + 1) % n) / n;
			B[s] = (num_t)((i * j + 2) % n) / n;
		});
	});
}

// computation kernel
//
// Original C kernel:
//
//   for (i = 0; i < _PB_N; i++) {
//     tmp[i] = 0.0;
//     y[i]   = 0.0;
//     for (j = 0; j < _PB_N; j++) {
//       tmp[i] = A[i][j] * x[j] + tmp[i];
//       y[i]   = B[i][j] * x[j] + y[i];
//     }
//     y[i] = alpha * tmp[i] + beta * y[i];
//   }
//
// This kernel keeps tmp[i] and y[i] in *scalar accumulators* (tmp_acc, y_acc)
// for each row i and writes them back once per row. This is algebraically
// equivalent but avoids O(N^2) loads/stores of tmp[i] and y[i], improving
// memory efficiency while preserving the mathematical result:
//
//   tmp[i] = Σ_j A[i,j] * x[j]
//   y[i]   = alpha * tmp[i] + beta * Σ_j B[i,j] * x[j]
//
[[gnu::flatten, gnu::noinline]]
void kernel_gesummv(num_t alpha, num_t beta, auto A, auto B, auto tmp, auto x, auto y) {
	using namespace noarr;

	#pragma scop
	traverser(A, B, tmp, x, y).template for_dims<'i'>([&](auto inner) {
		// inner traverser has 'i' fixed, 'j' remaining
		auto si = inner.state(); // state containing index_in<'i'>

		// Per-row accumulators kept in registers.
		// These replace repeated memory updates to tmp[i] and y[i].
		num_t tmp_acc = (num_t)0.0;
		num_t y_acc   = (num_t)0.0;

		// Inner loop over j for this fixed i.
		// Thanks to mat_layout = j_vec ^ i_vec, j is the contiguous
		// dimension in memory for A and B, and x is also contiguous in j.
		inner.for_each([&](auto s) {
			// s contains indices for 'i' and 'j'.
			// When indexing x, the extra 'i' index is ignored by Noarr.
			num_t xj = x[s]; // x[j]

			tmp_acc += A[s] * xj; // accumulate A[i,j] * x[j]
			y_acc   += B[s] * xj; // accumulate B[i,j] * x[j]
		});

		// Write back once per row i.
		// This exactly matches the algebraic result of the original kernel:
		//   tmp[i] == Σ_j A[i,j] * x[j]
		//   y[i]   == alpha * tmp[i] + beta * Σ_j B[i,j] * x[j]
		tmp[si] = tmp_acc;
		y[si]   = alpha * tmp_acc + beta * y_acc;
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;
	using namespace noarr;

	// problem size
	std::size_t n = N;

	// scalars
	num_t alpha;
	num_t beta;

	// common lengths for dimensions 'i' and 'j'
	auto set_lengths =
		set_length<'i'>(n) ^
		set_length<'j'>(n);

	// data structures
	auto A   = bag(scalar<num_t>() ^ mat_layout ^ set_lengths);
	auto B   = bag(scalar<num_t>() ^ mat_layout ^ set_lengths);
	auto tmp = bag(scalar<num_t>() ^ y_layout   ^ set_lengths); // length N in 'i'
	auto x   = bag(scalar<num_t>() ^ x_layout   ^ set_lengths); // length N in 'j'
	auto y   = bag(scalar<num_t>() ^ y_layout   ^ set_lengths); // length N in 'i'

	// initialize data
	init_array(alpha, beta, A.get_ref(), B.get_ref(), x.get_ref());

	// timing
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gesummv(alpha, beta,
	               A.get_ref(), B.get_ref(),
	               tmp.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optional: print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		serialize_data(std::cerr, y.get_ref() ^ hoist<'i'>());
	}

	// print elapsed time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
